int active()
{
    boolean ret = next active();

    SalesTable salesTable = this.cursor() as SalesTable;

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && salesTable && salesTable.isGUPSalesOrder() && !salesTable.MCROrderStopped)
    {
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, ButtonRetailRecalculator))).enabled(false);
    }
    return ret;
}

protected boolean shouldResetMcrParms()
{
    boolean ret = next shouldResetMcrParms();

    ret = ret || GUPParameters::asRetailSalesOrder();

    return ret;
}
